for(const s of project.codedSegments){const d=project.docs.find(d=>d.id===s.docId);if(!d||d.content.slice(s.start,s.end)!==s.text)throw Error('Invalid excerpt offsets: '+s.id);}
if(units.filter(u=>u.agreed).length<8||!pairwise.every(p=>p.kappa!==null&&p.contingency.aOnly+p.contingency.bOnly>0))throw Error('Demo lacks usable agreement/disagreement examples.');
if(!project.queries.every(q=>retrieveExcerpts(project,q).length>0))throw Error('A saved demo query returned no results.');
const allIds=[project.id,...project.docs.map(d=>d.id),...codes.map(c=>c.id),...project.codedSegments.map(s=>s.id),...project.memos.map(m=>m.id)];if(new Set(allIds).size!==allIds.length)throw Error('Duplicate IDs.');
const sentenceCoverage={uncoded:0,singleCoded:0,multipleCoded:0};for(const span of spans){for(const match of span.text.matchAll(/[^.!?]+(?:[.!?]+|$)/g)){if(!match[0].trim())continue;const midpoint=span.start+match.index+Math.floor(match[0].length/2),ids=new Set(project.codedSegments.filter(seg=>seg.coder==='Amina'&&seg.docId===docId(span.resident)&&seg.start<=midpoint&&seg.end>midpoint).map(seg=>seg.codeId));sentenceCoverage[ids.size===0?'uncoded':ids.size===1?'singleCoded':'multipleCoded']++;}}if(!Object.values(sentenceCoverage).every(n=>n>0))throw Error('Demo must contain uncoded, singly coded and multiply coded participant sentences.');
const manifest={fictional:true,sentenceCoverage,analysisPeriods:project.analysisPeriods.length,visualizationDrafts:project.mapDrafts.length,transcripts:project.docs.length,words:project.docs.reduce((n,d)=>n+d.content.split(/\s+/).length,0),codes:codes.length,coders:coders.map(coder=>({name:coder,codingEntries:project.codedSegments.filter(s=>s.coder===coder).length,transcripts:new Set(project.codedSegments.filter(s=>s.coder===coder).map(s=>s.docId)).size})),codingEntries:project.codedSegments.length,starred:project.codedSegments.filter(s=>s.starred).length,memosAndNotes:listMemoRecords(project).length,frameworkCells:project.frameworkCells.length,relationshipMemos:project.relationNotes.length,savedQueries:project.queries.length,agreements:units.filter(u=>u.agreed).length,reviewableGroups:units.filter(u=>u.distinctCoders>=2).length,checks:['Exact quote offsets verified','Unique core IDs verified','All saved queries return results','Every coder covers every transcript','Independent projects merge to 4 sources and matching coding-entry count','Pairwise ICR has non-null kappa and intentional disagreements']};write('MANIFEST.json',manifest);
(async()=>{const zip=new JSZip();function add(dir,prefix=''){for(const item of fs.readdirSync(dir,{withFileTypes:true})){const relative=prefix+item.name;if(item.isDirectory())add(path.join(dir,item.name),relative+'/');else zip.file(relative,fs.readFileSync(path.join(dir,item.name)));}}add(out);fs.writeFileSync(path.join(root,'eQc_Fictional_Climate_Demo.zip'),await zip.generateAsync({type:'nodebuffer',compression:'DEFLATE'}));console.log(JSON.stringify(manifest,null,2));})().catch(e=>{console.error(e);process.exitCode=1;});
